	(1, 'TWK', 'Tes Wawasan Kebangsaan', 30, 65, 150, 'binary', 'Mengukur pengetahuan dan kemampuan dalam mengimplementasikan nilai-nilai kebangsaan: Pancasila, UUD 1945, NKRI, dan Bhinneka Tunggal Ika. Penilaian: benar = 5 poin, salah = 0.', '2026-05-20 19:17:39'),
	(2, 'TIU', 'Tes Intelegensia Umum', 35, 80, 175, 'binary', 'Mengukur kemampuan verbal, numerik, dan figural. Meliputi analogi, silogisme, deret angka, dan kemampuan berpikir logis. Penilaian: benar = 5 poin, salah = 0.', '2026-05-20 19:17:39'),
	(3, 'TKP', 'Tes Karakteristik Pribadi', 45, 166, 225, 'gradual', 'Menilai karakter dan perilaku kerja ASN: pelayanan publik, jejaring kerja, sosial budaya, teknologi informasi, dan profesionalisme. Penilaian: tiap opsi memiliki poin 1-5, tidak ada jawaban salah.', '2026-05-20 19:17:39');
