INSERT INTO `soal` (`id_soal`, `id_kategori`, `pertanyaan`, `gambar`, `tingkat_kesulitan`, `status`, `dibuat_oleh`, `created_at`, `updated_at`) VALUES
	(12, 1, 'Dalam KTT Palestina di PBB, New York, Presiden Indonesia Prabowo Subianto menyampaikan pidato penting. Dalam pidatonya, Prabowo menegaskan dukungan Indonesia terhadap solusi dua negara sebagai jalan utama untuk perdamaian di Timur Tengah. Prabowo juga menyampaikan kesiapan Indonesia untuk ikut aktif menjaga perdamaian, salah satunya dengan menawarkan pasukan penjaga perdamaian. Dalam peristiwa tersebut jelas terlihat bahwa...', NULL, 'sedang', 'aktif', 1, '2026-05-29 15:55:53', '2026-05-29 15:55:53'),
	(14, 2, 'Pola selanjutnya adalah...', 'uploads/soal/soal_20260529133053_91df776d8174.png', 'sedang', 'aktif', 1, '2026-05-29 20:30:53', '2026-05-29 20:30:53'),
	(15, 3, 'Dalam rapat pimpinan sekolah terdapat rencana melengkapi ruang kelas dengan AC. Namun kamar mandi siswa rusak sehingga saat istirahat siswa harus antre menggunakan kamar mandi guru. Sebagai guru yang ikut rapat, tindakan yang paling tepat yaitu ...', NULL, 'sedang', 'aktif', 1, '2026-05-29 20:37:27', '2026-05-29 20:38:16'),
	(16, 1, 'Sebagai negara yang majemuk, sikap yang patut dimiliki oleh setiap warga negara adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-02 13:21:59', '2026-06-02 13:21:59'),
	(17, 1, 'Berdasarkan prinsip trias politica, kekuasaan negara dibagi menjadi tiga yaitu legislatif, eksekutif, dan yudikatif. Pembagian ini bertujuan untuk mencegah penyalahgunaan kekuasaan dan memastikan terjadinya check and balance antarlembaga negara...', NULL, 'sedang', 'aktif', 1, '2026-06-02 13:25:14', '2026-06-02 13:25:14'),
	(18, 1, 'Peraturan perundang-undangan di Indonesia mengenal adanya hierarki. Peraturan yang memiliki kedudukan tertinggi dalam hierarki peraturan perundang-undangan adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-02 13:27:52', '2026-06-02 14:15:15'),
	(20, 1, 'BPS Indonesia mencatat angka pengangguran di indonesia mencapai 7,28 juta per Februari 2025. Tidak hanya itu, Indonesia bahkan memperoleh peringkat pertama sebagai negara dengan pengangguran tertinggi se-Asia Tenggara berdasarkan Trading Economics, presentase pengangguran di indonesia sebesar 4,67%, tertinggi se-ASEAN. Manakah upaya yang kontras dengan hal tersebut...', NULL, 'sedang', 'aktif', 1, '2026-06-02 14:28:14', '2026-06-02 14:28:14'),
	(21, 1, 'Pemberian bantuan sosial kepada masyarakat miskin memang memiliki dampak yang baik. Namun, tidak sedikit adanya ketidaksepakatan sasaran penerima bantuan sosial. Hal ini disebabkan oleh berbagai faktor . Salah satunya adalah ketidak up to date data yang digunakan dalam upaya menaggulangi hal tersebut yang perlu dilakukan adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-02 14:44:28', '2026-06-02 14:44:28'),
	(22, 1, 'Tanggal 28 Oktober diperingati sebagai Hari Sumpah Pemuda. Tanggal tersebut menjadi Sejarah penting bagi bangsa ini yang menghasilkan ikrar sumpah pemuda. Berdasarkan ikrar yang telah disepakati, manakah nilai nasionalisme yang terkandung di dalam isi sumpah pemuda yang ke-3...', NULL, 'sedang', 'aktif', 1, '2026-06-02 14:47:40', '2026-06-02 14:47:40'),
	(23, 1, 'Saat ini siapa yang tak kenal menteri Purbaya? Gayanya yang ceplas-ceplos menjadi salah satu daya tarik masyarakat. Berbagai kebijakan pun diambil dan menjadi sorotan public diawal kepemimpinanya. Salah satu kebijakan yang menjadi angin segar adalah akan memerangi tekstil ilegal dari Tiongkok. Menurut Purbaya, tekstil ilegal dari Tingkok telah menguasai 99% pasar busana di tanah air, termasuk busana muslim. Pemerintah, berkomitmen melindungi industry tekstil lokal agar bisa bersaing sehat di pasar domestic. Nilai integritas yang tercemin pada kalimat terrakhir teks di atas adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:14:33', '2026-06-08 21:14:33'),
	(24, 1, 'Salah satu pejabat teladan yang pernah dimiliki bangs aini adalah Menteri Keuangan era Orde B Mar\'ie Muhammad. Ada kejadian unik saat beliau masih menjabat. Saat itu, Mar\'ie dijadwalkan menerima Bintang Mahaputra dari Presiden Soeharto. Jika pada umumnya tamu sekelas Menter datang menggunakan mobil mewah dan sopir, Mar\'ie justru memilih datang bersama istrinya menggunakan kijang tua keluaran 1980-an. Mobil itu merupakan mobil pribadinya, bukan mobil dinas. Setiba di gerbang istana negara, mobilnya diberhentikan oleh petugas keamanan yang tidak menyadari bahwa penumpangnya adalah seorang Menkeu. Penjaga keamanan mengira bahwa mereka adalah tamu biasa karena kendaraan mereka tampak tua. Namun, setelah Mar\'ie menunjukkan identitas dan menjelaskan maksud kedatangannya, para petugas pun buru-buru meminta maaf dan mempersilahkan masuk. Tindakannya tersebut bukan kebetulan. Mar\'ie memang berpegang pada prinsip mobil dinas hanya untuk urusan dinas, bukan untuk keperluan pribadi, kegemaran Mar\'le menggunakan mobil tua bukan tanpa alasan. Beliau dikenal tidak suka mengganti barang selama masih berfungsi dengan baik. Menurut sang anak, ayahnya berprinsip bahwa efisiensi lebih penting daripada gengsi. Nilai integritas yang mampu diteladani dari tokoh di atas adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:25:07', '2026-06-08 21:25:07'),
	(25, 1, 'Dalam menetapkan kebijakan umum pertahanan negara, Presiden dibantu Dewan Pertahanan Nasional, yang keanggotaannya terdiri atas anggota tetap dan anggota tidak tetap dengan hak dan kewajiban yang sama. Manakah yang bukan termasuk kedalam anggota tetap Dewan Pertahanan Nasional...', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:29:16', '2026-06-08 21:29:16'),
	(26, 1, 'Pengabdian sesuai profesi untuk bela negara adalah dimana seseorang menggunakan keterampilan, pengetahuan, dan keahlian sesuai bidangnya untuk mendukung dan memperkuat pertahanan negara dalam menghadapi ancaman. Diantara pengabdian sesuai profesi manakah yang kurang sinkron?', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:33:55', '2026-06-08 21:33:55'),
	(27, 1, 'Operasi militer pada dasarnya terdiri atas operas militer untuk perang dan operasi militer selain perang. Manakah yang tidak termasuk kedalam operasi militer selain perang?', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:38:26', '2026-06-08 21:38:26'),
	(28, 1, 'Perhatikan tugas-tugas berikut ini!\r\n\r\n1. Mempertahankan kedaulatan negara dan keutuhan wilayah\r\n2. Memberikan perlindungan, pengayoman, dan pelayanan kepada masyarakat\r\n3. Melindungi kehormatan dan keselamatan bangsa\r\n4. Melaksanakan operasi militer selain perang\r\n5. Ikut serta secara aktif dalam tugas pemeliharaan perdamaian regional dan  internasional\r\n6. Memelihara keamanan dan ketertiban masyarakat\r\n7. Menegakkan hukum\r\n\r\nManakah yang termasuk tugas TNI?', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:41:31', '2026-06-08 21:41:31'),
	(29, 1, 'Arina memiliki kebiasaan yang baik. Setiap hari, ia bangun pagi dan melaksanakan sholat shubuh. Saat sekolahnya libur, ia selalu berlari mengelilingi lapangan selama 30 menit. Kebiasaannya tersebut sudah ia lakukan sejak dirinya dibangku 3 SD. Saat ini, Arina sudah duduk di kelas XII SMA Nilai dasar bela negara yang tercermin pada diri Arina adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:44:15', '2026-06-08 21:44:15'),
	(30, 1, 'Kemerdekaan Indonesia yang diraih dengan tetesan darah nyatanya harus dipertahankan. Seluruh warga negara tanpa terkecuali harus turut serta mempertahankan negara sesuai dengan kemampuan yang dimiliki, salah satu bukti nyata bahwa setiap warga negara memiliki kewajiban dalam membela negaranya tercantum dalam UUD 1945. Berdasarkan kalimat pertama di atas, maka fungsi bela negara adalah.....', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:49:48', '2026-06-08 21:49:48'),
	(31, 1, 'Kewenangan pengerahan kekuatan TNI dalam rangka operasi militer berada di tangan...', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:51:24', '2026-06-08 21:51:24'),
	(32, 1, 'UUD 1945 terdiri atas empat bagian, yaitu Pembukaan, Batang tubuh, Aturan peralihan, dan aturan tambahan. Kedudukan pembukaan UUD 1945 terbagi menjadi 4 alinea. Dari berbagai makna yang ada, manakah yang termasuk kedalam salah satu makna pada pembukaan UUD 1945 alinea ke-3?', NULL, 'sedang', 'aktif', 1, '2026-06-08 21:57:19', '2026-06-08 21:57:19'),
	(33, 1, 'Amandemen UUD 1945 ke-4 memberikan perubahan penting dalam struktur dan substansi  UUD 1945. Salah satu Lembaga negara yang dihapus pada amandemen kala itu adalah...', NULL, 'sedang', 'aktif', 1, '2026-06-08 22:00:23', '2026-06-08 22:00:23'),
	(34, 1, 'Sebagai ideologi terbuka, Pancasila mempunyai dimensi fleksibilitas, karena di dalamnya terkandung beberapa nilai. Nilai yang terkandung dalam Pancasila terbagi menjadi nilai dasar, nilai instrumental, dan nilai praktis. Manakah yang sinkron dengan nilai dasar yang terdapat pada Pancasila?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:06:30', '2026-06-09 15:06:30'),
	(35, 1, 'Pasal 34 ayat 3 UUD 1945 berbunyi: Negara bertanggung jawab atas penyediaan fasilitas pelayanan Kesehatan dan fasilitas pelayanan umum yang layak. Manakah yang senada dengan hal tersebut?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:10:31', '2026-06-09 15:10:31'),
	(36, 1, 'Urusan pemerintahan absolut sebagaimana dimaksud dalam pasal 9 ayat (2) pada UU otonomi daerah meliputi; politik luar negeri, pertahanan, keamanan, yustisi, moneter dan fiscal nasional, dan agama. Di bawah ini yang termasuk kedalam urusan yustisi adalah.....', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:13:00', '2026-06-09 15:13:00'),
	(37, 1, 'Pasal 30 UUD 1945 ayat 1 berbunyi: Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara. Adapun hak dan kewajiban warga negara dalam usaha pertahanan negara demi menjaga keamanan negara sebagaimana diamanatkan dalam UUD 1945 diatur lebih lanjut dalam UU 3/2002 tentang pertahanan negara. Manakah yang selaras dengan hal tersebut?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:16:52', '2026-06-09 15:16:52'),
	(38, 1, 'Pancasila sebagai ideologi, bersifat terbuka yang memiliki arti tidak kaku dan dogmatis, melainkan fleksibel dan adaptif terhadap perubahan zaman. Manakah hal yang tidak sesuai dengan pernyataan tersebut?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:19:17', '2026-06-09 15:19:17'),
	(39, 1, 'Perhatikan teks berikut ini!\r\n\r\nDi ujung barat Pulau Papua, Kabupaten Tambrauw berdiri sebagai benteng keanekaragaman hayati yang kaya di darat maupun laut. Sejak mendeklarasikan diri sebagai Kabupaten Konservasi pada 2018, wilayah ini terus meneguhkan komitmennya menjaga alam, budaya, dan keberlangsungan hidup warganya, terutama masyarakat adat. Untuk memperkuat upaya tersebut, Yayasan Konservasi Alam Nusantara (YKAN) hadir di Tambrauw sejak 2021. YKAN tidak hanya memba ya pendekatan konservasi konvensional, tetapi juga mendorong pengelolaan wilayah berbasis hak kelola adat. Upaya tersebut sejalan dengan Peraturan Bupati Tambrauw Nomor 12 Tahun 2019 yang secara resmi mengakui hak masyarakat adat Werur dalam mengelola sumber daya pesisir dan laut mereka. "Dengan dukungan dari YKAN, wilayah-wilayah adat yang penting kini telah dimasukkan dalam Rancangan Perda Tata Ruang Provinsi Papua Barat Daya. Ini upaya penting agar wilayah tersebut terlindungi dalam berbagai skema kebijakan," ujar Kepala Dinas Pertanian, Pangan, Kelautan dan Perikanan Papua Barat Daya, Absalom Solossa.\r\n\r\nla menuturkan, Kabupaten Tambrauw yang menjadi bagian dari Bentang Laut Kepala Burung Papua memiliki kekayaan laut luar biasa yang menjadi sumber penghidupan masyarakat. "Kami tidak bisa bekerja sendiri. Perlu kerja sama dengan mitra pembangunan seperti YKAN yang terus mendukung langkah strategis kami dalam konservasi," tambahnya. Salah satu kekuatan pendekatan YKAN adalah keterlibatan masyarakat sejak awal melalui mekanisme Padiatapa (Persetujuan Atas Dasar Informasi di Awal Tanpa Paksaan). Mekanisme ini dijalankan di Tambrauw sejak 2021 dan diperbaharui pada Januari 2025, dengan melibatkan dewan adat, gereja, pemuda, dan kelompok perempuan.\r\n\r\nKini, YKAN aktif mendampingi enam kampung di Distrik Bikar-mulai dari Werur hingga Werbes -untuk mengelola wilayah perairan adat seluas 12.000 hektare. Pendampingan ini mencakup penguatan kelompok ekonomi lokal, pendidikan lingkungan, dan pengelolaan perikanan berbasis masyarakat yang memadukan sains dan teknologi. Satu hal menarik adalah dukungan YKAN terhadap praktik sasi laut di perairan Pulau Dua. Sasi, yang digagas Dewan Adat Byak Karon bersama gereja, merupakan sistem adat pelarangan sementara penangkapan hasil laut untuk menjaga keseimbangan ekosistem, YKAN membantu memperkuat pemahaman dan kapasitas masyarakat dalam menjaga kawasan sasi tersebut. "YKAN hadir bukan untuk menggantikan peran siapa pun, tetapi sebagai mitra yang menghormati budaya lokal dan wewenang masyarakat yang memadukan sains dan teknologi. Satu hal menarik adalah dukungan YKAN terhadap praktik sasi laut di perairan Pulau Dua. Sasi, yang digagas Dewan Adat Byak Karon bersama gereja, merupakan sistem adat pelarangan sementara penangkapan hasil laut untuk menjaga keseimbangan ekosistem. YKAN membantu memperkuat pemahaman dan kapasitas masyarakat dalam menjaga kawasan sasi tersebut. "YKAN hadir bukan untuk menggantikan peran siapa pun, tetapi sebagai mitra yang menghormati budaya lokal dan wewenang pemerintah," tegas Direktur Program Kelautan YKAN, Muhammad Ilman dalam keterangan persnya yang diterima Berita Lingkungan.com (25/06/2025).  "Kami percaya, pelestarian hanya akanı bermakna jika membawa manfaat nyata bagi masyarakat dan dapat diwariskan ke generasi mendatang,ujarnya.\r\n\r\nLangkah kolaboratif antara pemerintah, masyarakat adat, dan mitra konservasi seperti YKAN ini memberi harapan bahwa pengelolaan lestari bukan hanya impian, tetapi bisa menjadi kenyataan di tanah Papua (Marwan Aziz).\r\n\r\nBerdasarkan letak pikiran utamanya, paragraph di atas termasuk kedalam jenis paragraph...', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:26:47', '2026-06-09 15:33:02'),
	(40, 1, 'Perhatikan teks berikut ini!\r\n\r\nMenteri Kesehatan (Menkes) Budi Gunadi Sadikin mengimbau masyarakat untuk tidak beraktivitas di luar ruangan setelah hujan turun, menyusul temuan Badan Riset dan Inovasi Nasional (BRIN) yang mendeteksi kandungan mikroplastik dalam air hujan di Jakarta. la juga meminta warga mengenakan masker saat beraktivitas, mengingat mikroplastik yang terbawa udara dan hujan dapat bertahan lama di tubuh manusia jika terhirup atau tertelan. "Imbauan saya buat masyarakat adalah ya kalau bisa yang paling aman melindunginya pakai masker kalau jalan di luar. Tapi kalau tidak, ya usahakan jangan jalan di luar sesudah hujan karena ini turunnya kan dekat-dekat hujannya kan, partikelnya," ucap Budi usai bertemu Gubernur DKI Jakarta Pramono Anung di Gedung Kernenterian Kesehatan, Kuningan, Jakarta Selatan, Selasa (28/10/2025).\r\n\r\nDi sisi lain, Budi menilai pencegahan harus dilakukan sejak awal dengan mengurangi sumber polusi plastik di lingkungan. la pun meminta Pramono untuk ikut berperan dalam mengatasinya. "Mungkin pencegahan lainnya ya paling bagus memang di hulunya. Artinya memang kita mesti mengurangi sumber polusi dari mikroplastik ini, dan ini memang peranan Pak Gubernur (Pramono) penting sekali. Pak Gub berperan banyak, polusinya berkurang, kita di Kementerian Kesehatan juga akan sangat berkurang bebannya," ucap Budi. Kasus Keracunan MBC, Presiden: Ini Masalah Besar Artikel Kompas.id Menanggapi hal itu, Pramono memastikan akan menindaklanjuti temuan BRIN bersama Dinas Lingkungan Hidup (DLH). la mengatakan Pemprov DKI bakal mempercepat program pengolahan sampah menjadi energi listrik (PLTSA) dan langkah lain untuk menekan limbah plastik. "Kami segera untuk hal yang berkaitan dengan plastik, terus terang untuk PLTSA dan sebagainya akan segera kita realisasikan. Tetapi saya setuju bahwa memang untuk pencegahan di awal, masyarakat harus prepare untuk menggunakan masker," ungkap Pramono la juga menambahkan, dalam beberapa hari terakhir Jakarta terlihat lebih bersih dan hijau, terutama selama acara Jakarta Running Festival berlangsung pada Sabtu (25/10/2025) dan Minggu (26/10/2025) kemarin. "Tetapi yang saya senang, tiga hari ini, karena ada Jakarta Running Festival itu Jakarta enggak tahu hijau semuanya, bahkan bersih banget, bersih banget tiga hari ini. Jadi itu keadaan kita pada saat ini," lanjut Pramono. Sebelumnya, Peneliti Ahli Utama Pusat Riset Oseanografi BRIN, Reza, menjelaskan air hujan di Jakarta telah terkontaminasi mikroplastik yang bersifat toksik atau beracun. la mengungkapkan, temuannya itu bukan sekadar dugaan, melainkan hasil penelitian yang pernah ia pimpin dan telah dipublikasikan dalam jurnal Science Direct naria Januar 2032 "Saat ini caua menjadi neneliti utamania" kata Reza saat dihubungi Oseanografi BRIN, Reza, menjelaskan air hujan di Jakarta telah terkontaminasi mikroplastik yan bersifat toksik atau beracun. la mengungkapkan, temuannya itu bukan sekadar dugaan, melainkan hasil penelitian yang pernah ia pimpin dan telah dipublikasikan dalam jurnal Science Direct pada Januari 2022. "Saat itu saya menjadi peneliti utamanya," kata Reza saat dihubungi Kompas.com, Senin (13/10/2025). Studi yang dilakukan selama 12 bulan penuh ini mendeteksi adanya partikel mikroplastik dalam tiap tetes hujan yang jatuh di ibu kota. Pengumpulan data dilakukan menggunakan rain gauge dan ombrometer, sebelum dianalisis melalui teknologi Fourier Transform infrared Spectroscopy (FTIR) untuk mengidentifikasi jenis polimer plastik. Baca juga: Dinkes DKI Minta Warga Rutin Bersihkan Rumah untuk Cegah Mikroplastik "Hasilnya menunjukkan laju deposisi mikroplastik di Jakarta mencapai 3 hingga 40 partikel per meter persegi per hari, dengan rata-rata 15 partikel, "Ujar Reza".\r\n\r\nGagasan utama teks di atas terdapat pada kalimat.....', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:39:35', '2026-06-09 15:39:35'),
	(41, 1, 'Manakah yang  termasuk kedalam kalimat efektif?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:43:35', '2026-06-09 15:43:35'),
	(42, 1, 'Penggunaan huruf kapital yang tepat terdapat pada kalimat.....', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:47:09', '2026-06-09 15:47:09'),
	(43, 1, 'Perhatikan teks berikut ini!\r\n\r\nTak pernah terlintas di benak Mustafa bahwa dirinya akan menjadi seorang pekebun alpukat. Sebelum mengenal dunia pertanian, pria kelahiran 1975 itu menghabiskan 15 tahun hidupnya sebagai kontraktor dan pedagang alat berat. la bahkan sempat mengekspor alat berat bekas yang telah diperbaiki hingga ke Dubai, Uni Emirat Arab. "Pekerjaan saya dulu lebih banyak menjual danı membeli alat berat bekas pertambangan," kenangnya. Beberapa unit alat berat yang tak terpakal diambil komponennya seperti mesin dan hidrolik, sedangkan sisanya dilebur. Di sela-sela bisnis alat berat, Mustafa juga merintis usaha properti yang hingga kini masih berjalan.\r\n\r\nPerjalanan Mustafa ke dunia hijau dimulai secara tidak sengaja. Suatu ketika, sebuah yayasan yang pernah dibantunya dengan alat berat memberikan lahan seluas lima hektare di Megamendung. Kabupaten Bogor, untuk dikelola. "Saya bingung karena latar belakang saya bukan petani," ujarnya. Setelah berdiskusi dengan seorang rekan, Mustafa mendapat saran untuk menanam alpukat hass, varietas unggul yang tengah naik daun di pasar global. la pun mencoba, tanpa menyangka langkah itu akan membuka jalan menuju kesuksesan baru.\r\n\r\nKini Mustafa menjadi pendiri PT Spektani Berkah Agro, produsen alpukat hass dengan permintaan ekspor yang terus mengalir. Negara seperti Jepang, Malaysia, dan Singapura rutin memesan buah hass dari kebunnya. "Dari Jepang saja permintaannya bisa mencapai 20 ton per bulan. Malaysia juga 20 ton, dan Singapura 5-10 ton per bulan," katan\r\n\r\nPermintaan besar itu belum seluruhnya bisa dipenuhi karena kapasitas produksi masih terbatas Meski begitu, peluang pasar yang luas membuat Mustafa semakin bersemangat memperluas kebun dan meningkatkan hasil panen. Harga alpukat hass di pasaran mencapai Rp120.000 per kilogram, bahkan bisa menembus Rp200.000 per kilogram. Harga paling murah pun masih di kisaran Rp100.000 per kilogram angka yang menggiurkan bagi petani lokal. Menurut Mustafa, buah hass punya banyak keunggulan. Rasanya enak, lembut, sedikit asin, dan berlemak tinggi Bobot buah relatif kecil, antara 170-300 gram, namun kulitnya tebal sehingga tahan lama dan cocok untuk ekspor jarak jauh. "Kalau dipanen muda, daging buahnya menempel di biji. Jadi harus benar-benar matang di pohon," jelasnya. Buah hass yang dipanen dengan tepat bisa bertahan 10-14 hari di suhu ruang, sehingga ideal untuk komoditas ekspor premium.\r\n\r\nKisah Mustafa membuktikan bahwa keberhasilan di dunia pertanian tak selalu berawal dari latar belakana agronomi. Dengan semangat belajar dan tekad kuat ia berhasil mengubah lahan percobaan menjadi kebun produktif bernilai tinggi. Kini, selain menjadi petani sukses, Mustafa bertahan 10-14 hari di suhu ruang, sehingga ideal untuk komoditas ekspor premium.\r\n\r\nKisah Mustafa membuktikan bahwa keberhasilan di dunia pertanian tak selalu berawal dari latar belakang agronomi. Dengan semangat belajar dan tekad kuat, ia berhasil mengubah lahan percobaan menjadi kebun produktif bernilai tinggi. Kini, selain menjadi petani sukses, Mustafa juga menjadi inspirasi bagi banyak orang yang ingin terjun ke sektor pertanian modern. "Awalnya saya tidak tahu apa-apa tentang pertanian," ujarnya sambil tersenyum. "Ternyata kalau ditekuni, hasilnya luar biasa"\r\n\r\nManakah pernyataan yang tidak sesuai?', NULL, 'sedang', 'aktif', 1, '2026-06-09 15:56:34', '2026-06-09 15:56:34'),
