CREATE DATABASE IF NOT EXISTS `db_tryout_cpns` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci */ /*!80016 DEFAULT ENCRYPTION='N' */;
USE `db_tryout_cpns`;

CREATE TABLE IF NOT EXISTS `detail_hasil` (
  `id_detail` int unsigned NOT NULL AUTO_INCREMENT,
  `id_hasil` int unsigned NOT NULL,
  `id_soal` int unsigned NOT NULL,
  `id_opsi_dipilih` int unsigned DEFAULT NULL COMMENT 'NULL = tidak menjawab',
  `jawaban_peserta` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode opsi yang dipilih: A/B/C/D/E atau NULL',
  `poin_didapat` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT 'TWK/TIU: 5 atau 0 | TKP: 1-5 atau 0',
  `is_benar` tinyint(1) DEFAULT NULL COMMENT 'TWK/TIU: 1=benar,0=salah | TKP: NULL (tidak relevan)',
  `urutan_tampil` smallint unsigned DEFAULT NULL COMMENT 'Urutan soal saat peserta mengerjakan (sudah diacak)',
  PRIMARY KEY (`id_detail`),
  UNIQUE KEY `uq_hasil_soal` (`id_hasil`,`id_soal`),
  KEY `fk_detail_opsi` (`id_opsi_dipilih`),
  KEY `idx_hasil` (`id_hasil`),
  KEY `idx_soal` (`id_soal`),
  CONSTRAINT `fk_detail_hasil` FOREIGN KEY (`id_hasil`) REFERENCES `hasil` (`id_hasil`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_detail_opsi` FOREIGN KEY (`id_opsi_dipilih`) REFERENCES `opsi_jawaban` (`id_opsi`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `fk_detail_soal` FOREIGN KEY (`id_soal`) REFERENCES `soal` (`id_soal`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=441 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Detail jawaban peserta per soal per sesi tryout';

DELETE FROM `detail_hasil`;

CREATE TABLE IF NOT EXISTS `hasil` (
  `id_hasil` int unsigned NOT NULL AUTO_INCREMENT,
  `id_user` int unsigned NOT NULL,
  `id_tryout` int unsigned NOT NULL,
  `nilai_twk` decimal(6,2) NOT NULL DEFAULT '0.00',
  `nilai_tiu` decimal(6,2) NOT NULL DEFAULT '0.00',
  `nilai_tkp` decimal(6,2) NOT NULL DEFAULT '0.00',
  `total_nilai` decimal(6,2) NOT NULL DEFAULT '0.00',
  `benar_twk` tinyint unsigned NOT NULL DEFAULT '0',
  `benar_tiu` tinyint unsigned NOT NULL DEFAULT '0',
  `lulus_twk` tinyint(1) NOT NULL DEFAULT '0',
  `lulus_tiu` tinyint(1) NOT NULL DEFAULT '0',
  `lulus_tkp` tinyint(1) NOT NULL DEFAULT '0',
  `lulus_total` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = lulus semua komponen SKD',
  `ranking` smallint unsigned DEFAULT NULL,
  `waktu_mulai` datetime NOT NULL,
  `waktu_selesai` datetime DEFAULT NULL,
  `durasi_detik` mediumint unsigned DEFAULT NULL COMMENT 'Selisih waktu_selesai - waktu_mulai dalam detik',
  `status_pengerjaan` enum('sedang','selesai','timeout') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sedang',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_hasil`),
  UNIQUE KEY `uq_user_tryout` (`id_user`,`id_tryout`),
  KEY `idx_user` (`id_user`),
  KEY `idx_tryout` (`id_tryout`),
  KEY `idx_total` (`total_nilai`),
  KEY `idx_lulus` (`lulus_total`),
  CONSTRAINT `fk_hasil_tryout` FOREIGN KEY (`id_tryout`) REFERENCES `tryout` (`id_tryout`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_hasil_user` FOREIGN KEY (`id_user`) REFERENCES `user` (`id_user`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rekap nilai akhir peserta per sesi tryout';

DELETE FROM `hasil`;

CREATE TABLE IF NOT EXISTS `kategori` (
  `id_kategori` int unsigned NOT NULL AUTO_INCREMENT,
  `kode` enum('TWK','TIU','TKP') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_kategori` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `jumlah_soal` tinyint unsigned NOT NULL DEFAULT '0' COMMENT 'Jumlah soal standar: TWK=30, TIU=35, TKP=45',
  `nilai_min` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Passing grade: TWK=65, TIU=80, TKP=166',
  `nilai_maks` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Nilai maks: TWK=150, TIU=175, TKP=225',
  `tipe_penilaian` enum('binary','gradual') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'binary=TWK/TIU (benar/salah), gradual=TKP (poin per opsi)',
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_kategori`),
  UNIQUE KEY `uq_kode` (`kode`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Kategori soal SKD: TWK, TIU, TKP';

DELETE FROM `kategori`;

CREATE TABLE IF NOT EXISTS `opsi_jawaban` (
  `id_opsi` int unsigned NOT NULL AUTO_INCREMENT,
  `id_soal` int unsigned NOT NULL,
  `kode_opsi` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'A, B, C, D, atau E',
  `teks_opsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Isi teks pilihan jawaban jika ada',
  `gambar_opsi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path gambar opsi jawaban jika ada',
  `poin` decimal(5,2) NOT NULL DEFAULT '0.00' COMMENT 'TWK/TIU: 5 (benar) atau 0 (salah) | TKP: 1–5',
  `is_kunci` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'TRUE = jawaban benar (hanya untuk TWK/TIU)',
  PRIMARY KEY (`id_opsi`),
  UNIQUE KEY `uq_soal_kode` (`id_soal`,`kode_opsi`),
  KEY `idx_soal` (`id_soal`),
  CONSTRAINT `fk_opsi_soal` FOREIGN KEY (`id_soal`) REFERENCES `soal` (`id_soal`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=671 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Opsi jawaban per soal (1 baris per opsi A-E)';

DELETE FROM `opsi_jawaban`;

CREATE TABLE IF NOT EXISTS `soal` (
  `id_soal` int unsigned NOT NULL AUTO_INCREMENT,
  `id_kategori` int unsigned NOT NULL,
  `pertanyaan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `gambar` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path gambar soal jika ada',
  `tingkat_kesulitan` enum('mudah','sedang','sulit') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sedang',
  `status` enum('aktif','nonaktif','draft') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `dibuat_oleh` int unsigned DEFAULT NULL COMMENT 'FK ke user (admin)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_soal`),
  KEY `fk_soal_user` (`dibuat_oleh`),
  KEY `idx_kategori` (`id_kategori`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_soal_kategori` FOREIGN KEY (`id_kategori`) REFERENCES `kategori` (`id_kategori`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_soal_user` FOREIGN KEY (`dibuat_oleh`) REFERENCES `user` (`id_user`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=125 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Bank soal SKD CPNS';

DELETE FROM `soal`;

DELIMITER //
CREATE PROCEDURE `sp_hitung_nilai`(IN p_id_hasil INT UNSIGNED)
BEGIN
    DECLARE v_twk   DECIMAL(6,2) DEFAULT 0;
    DECLARE v_tiu   DECIMAL(6,2) DEFAULT 0;
    DECLARE v_tkp   DECIMAL(6,2) DEFAULT 0;
    DECLARE v_total DECIMAL(6,2) DEFAULT 0;
    DECLARE v_benar_twk TINYINT  DEFAULT 0;
    DECLARE v_benar_tiu TINYINT  DEFAULT 0;

    -- Hitung nilai TWK (binary: poin dari opsi_jawaban)
    SELECT COALESCE(SUM(oj.poin), 0),
           COALESCE(SUM(CASE WHEN oj.is_kunci = 1 THEN 1 ELSE 0 END), 0)
    INTO v_twk, v_benar_twk
    FROM detail_hasil dh
    JOIN soal s         ON s.id_soal    = dh.id_soal
    JOIN kategori k     ON k.id_kategori= s.id_kategori
    JOIN opsi_jawaban oj ON oj.id_opsi  = dh.id_opsi_dipilih
    WHERE dh.id_hasil = p_id_hasil
      AND k.kode = 'TWK';

    -- Hitung nilai TIU (binary)
    SELECT COALESCE(SUM(oj.poin), 0),
           COALESCE(SUM(CASE WHEN oj.is_kunci = 1 THEN 1 ELSE 0 END), 0)
    INTO v_tiu, v_benar_tiu
    FROM detail_hasil dh
    JOIN soal s         ON s.id_soal    = dh.id_soal
    JOIN kategori k     ON k.id_kategori= s.id_kategori
    JOIN opsi_jawaban oj ON oj.id_opsi  = dh.id_opsi_dipilih
    WHERE dh.id_hasil = p_id_hasil
      AND k.kode = 'TIU';

    -- Hitung nilai TKP (gradual: semua poin dijumlah)
    SELECT COALESCE(SUM(oj.poin), 0)
    INTO v_tkp
    FROM detail_hasil dh
    JOIN soal s         ON s.id_soal    = dh.id_soal
    JOIN kategori k     ON k.id_kategori= s.id_kategori
    JOIN opsi_jawaban oj ON oj.id_opsi  = dh.id_opsi_dipilih
    WHERE dh.id_hasil = p_id_hasil
      AND k.kode = 'TKP';

    SET v_total = v_twk + v_tiu + v_tkp;

    -- Update tabel hasil
    UPDATE hasil SET
        nilai_twk    = v_twk,
        nilai_tiu    = v_tiu,
        nilai_tkp    = v_tkp,
        total_nilai  = v_total,
        benar_twk    = v_benar_twk,
        benar_tiu    = v_benar_tiu,
        lulus_twk    = IF(v_twk  >= 65,  1, 0),
        lulus_tiu    = IF(v_tiu  >= 80,  1, 0),
        lulus_tkp    = IF(v_tkp  >= 166, 1, 0),
        lulus_total  = IF(v_twk >= 65 AND v_tiu >= 80 AND v_tkp >= 166, 1, 0),
        status_pengerjaan = 'selesai',
        waktu_selesai     = NOW(),
        durasi_detik      = TIMESTAMPDIFF(SECOND, waktu_mulai, NOW())
    WHERE id_hasil = p_id_hasil;

    -- Update poin_didapat & is_benar di detail_hasil
    UPDATE detail_hasil dh
    JOIN opsi_jawaban oj ON oj.id_opsi   = dh.id_opsi_dipilih
    JOIN soal s          ON s.id_soal    = dh.id_soal
    JOIN kategori k      ON k.id_kategori= s.id_kategori
    SET
        dh.poin_didapat = oj.poin,
        dh.is_benar     = CASE
                            WHEN k.tipe_penilaian = 'binary'
                                 THEN oj.is_kunci
                            ELSE NULL   -- TKP: is_benar tidak relevan
                          END
    WHERE dh.id_hasil = p_id_hasil;

END//
DELIMITER ;

DELIMITER //
CREATE PROCEDURE `sp_update_ranking`(IN p_id_tryout INT UNSIGNED)
BEGIN
    SET @rnk = 0;
    UPDATE hasil h
    JOIN (
        SELECT id_hasil,
               (@rnk := @rnk + 1) AS rnk
        FROM hasil
        WHERE id_tryout = p_id_tryout
          AND status_pengerjaan = 'selesai'
        ORDER BY total_nilai DESC, waktu_selesai ASC
    ) ranked ON ranked.id_hasil = h.id_hasil
    SET h.ranking = ranked.rnk;
END//
DELIMITER ;

CREATE TABLE IF NOT EXISTS `tryout` (
  `id_tryout` int unsigned NOT NULL AUTO_INCREMENT,
  `nama_tryout` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `deskripsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `waktu` smallint unsigned NOT NULL DEFAULT '100' COMMENT 'Durasi ujian dalam menit',
  `jml_soal_twk` tinyint unsigned NOT NULL DEFAULT '30',
  `jml_soal_tiu` tinyint unsigned NOT NULL DEFAULT '35',
  `jml_soal_tkp` tinyint unsigned NOT NULL DEFAULT '45',
  `tanggal_mulai` datetime NOT NULL,
  `tanggal_selesai` datetime NOT NULL,
  `status` enum('draft','aktif','selesai','diarsipkan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `acak_soal` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = soal diacak untuk setiap peserta',
  `acak_opsi` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = urutan opsi A-E ikut diacak',
  `dibuat_oleh` int unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_tryout`),
  KEY `fk_tryout_user` (`dibuat_oleh`),
  KEY `idx_status` (`status`),
  KEY `idx_tanggal_mulai` (`tanggal_mulai`),
  KEY `idx_tanggal_selesai` (`tanggal_selesai`),
  CONSTRAINT `fk_tryout_user` FOREIGN KEY (`dibuat_oleh`) REFERENCES `user` (`id_user`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Sesi tryout yang dibuat admin';

DELETE FROM `tryout`;

CREATE TABLE IF NOT EXISTS `tryout_soal` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `id_tryout` int unsigned NOT NULL,
  `id_soal` int unsigned NOT NULL,
  `urutan` smallint unsigned NOT NULL DEFAULT '0' COMMENT 'Urutan tampil soal dalam tryout',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_tryout_soal` (`id_tryout`,`id_soal`),
  KEY `idx_tryout` (`id_tryout`),
  KEY `idx_soal` (`id_soal`),
  CONSTRAINT `fk_ts_soal` FOREIGN KEY (`id_soal`) REFERENCES `soal` (`id_soal`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_ts_tryout` FOREIGN KEY (`id_tryout`) REFERENCES `tryout` (`id_tryout`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1461 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Soal-soal yang digunakan dalam setiap sesi tryout';

DELETE FROM `tryout_soal`;

CREATE TABLE IF NOT EXISTS `user` (
  `id_user` int unsigned NOT NULL AUTO_INCREMENT,
  `nama` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `password` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'bcrypt hash',
  `no_hp` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` enum('admin','peserta') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'peserta',
  `status` enum('aktif','nonaktif') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'aktif',
  `foto` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'path file foto profil',
  `last_login` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_user`),
  UNIQUE KEY `uq_email` (`email`),
  KEY `idx_role` (`role`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Akun pengguna sistem (admin dan peserta)';

DELETE FROM `user`;

CREATE TABLE `v_dashboard_admin` (
	`id_tryout` INT UNSIGNED NOT NULL,
	`nama_tryout` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`status` ENUM('draft','aktif','selesai','diarsipkan') NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`tanggal_mulai` DATETIME NOT NULL,
	`tanggal_selesai` DATETIME NOT NULL,
	`total_peserta` BIGINT NOT NULL,
	`rata_nilai` DECIMAL(6,1) NULL,
	`nilai_tertinggi` DECIMAL(6,2) NULL,
	`nilai_terendah` DECIMAL(6,2) NULL,
	`jumlah_lulus` DECIMAL(25,0) NULL,
	`pct_lulus` DECIMAL(30,1) NULL
) ENGINE=MyISAM;

CREATE TABLE `v_rekap_nilai` (
	`id_hasil` INT UNSIGNED NOT NULL,
	`id_user` INT UNSIGNED NOT NULL,
	`nama_peserta` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`email` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`id_tryout` INT UNSIGNED NOT NULL,
	`nama_tryout` VARCHAR(1) NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`tanggal_mulai` DATETIME NOT NULL,
	`nilai_twk` DECIMAL(6,2) NOT NULL,
	`nilai_tiu` DECIMAL(6,2) NOT NULL,
	`nilai_tkp` DECIMAL(6,2) NOT NULL,
	`total_nilai` DECIMAL(6,2) NOT NULL,
	`benar_twk` TINYINT UNSIGNED NOT NULL,
	`benar_tiu` TINYINT UNSIGNED NOT NULL,
	`lulus_twk` TINYINT(1) NOT NULL,
	`lulus_tiu` TINYINT(1) NOT NULL,
	`lulus_tkp` TINYINT(1) NOT NULL,
	`lulus_total` TINYINT(1) NOT NULL COMMENT '1 = lulus semua komponen SKD',
	`ranking` SMALLINT UNSIGNED NULL,
	`durasi_detik` MEDIUMINT UNSIGNED NULL COMMENT 'Selisih waktu_selesai - waktu_mulai dalam detik',
	`waktu_mulai` DATETIME NOT NULL,
	`waktu_selesai` DATETIME NULL,
	`status_pengerjaan` ENUM('sedang','selesai','timeout') NOT NULL COLLATE 'utf8mb4_unicode_ci'
) ENGINE=MyISAM;

CREATE TABLE `v_statistik_soal` (
	`id_soal` INT UNSIGNED NOT NULL,
	`pertanyaan` TEXT NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`kategori` ENUM('TWK','TIU','TKP') NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`tipe_penilaian` ENUM('binary','gradual') NOT NULL COMMENT 'binary=TWK/TIU (benar/salah), gradual=TKP (poin per opsi)' COLLATE 'utf8mb4_unicode_ci',
	`tingkat_kesulitan` ENUM('mudah','sedang','sulit') NOT NULL COLLATE 'utf8mb4_unicode_ci',
	`total_dijawab` BIGINT NOT NULL,
	`total_benar` DECIMAL(23,0) NULL,
	`pct_benar` DECIMAL(28,1) NULL,
	`rata_poin` DECIMAL(6,2) NULL
) ENGINE=MyISAM;

DROP TABLE IF EXISTS `v_dashboard_admin`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_dashboard_admin` AS select `t`.`id_tryout` AS `id_tryout`,`t`.`nama_tryout` AS `nama_tryout`,`t`.`status` AS `status`,`t`.`tanggal_mulai` AS `tanggal_mulai`,`t`.`tanggal_selesai` AS `tanggal_selesai`,count(distinct `h`.`id_user`) AS `total_peserta`,round(avg(`h`.`total_nilai`),1) AS `rata_nilai`,max(`h`.`total_nilai`) AS `nilai_tertinggi`,min(`h`.`total_nilai`) AS `nilai_terendah`,sum(`h`.`lulus_total`) AS `jumlah_lulus`,round(((sum(`h`.`lulus_total`) / nullif(count(`h`.`id_hasil`),0)) * 100),1) AS `pct_lulus` from (`tryout` `t` left join `hasil` `h` on(((`h`.`id_tryout` = `t`.`id_tryout`) and (`h`.`status_pengerjaan` = 'selesai')))) group by `t`.`id_tryout`;

DROP TABLE IF EXISTS `v_rekap_nilai`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_rekap_nilai` AS select `h`.`id_hasil` AS `id_hasil`,`u`.`id_user` AS `id_user`,`u`.`nama` AS `nama_peserta`,`u`.`email` AS `email`,`t`.`id_tryout` AS `id_tryout`,`t`.`nama_tryout` AS `nama_tryout`,`t`.`tanggal_mulai` AS `tanggal_mulai`,`h`.`nilai_twk` AS `nilai_twk`,`h`.`nilai_tiu` AS `nilai_tiu`,`h`.`nilai_tkp` AS `nilai_tkp`,`h`.`total_nilai` AS `total_nilai`,`h`.`benar_twk` AS `benar_twk`,`h`.`benar_tiu` AS `benar_tiu`,`h`.`lulus_twk` AS `lulus_twk`,`h`.`lulus_tiu` AS `lulus_tiu`,`h`.`lulus_tkp` AS `lulus_tkp`,`h`.`lulus_total` AS `lulus_total`,`h`.`ranking` AS `ranking`,`h`.`durasi_detik` AS `durasi_detik`,`h`.`waktu_mulai` AS `waktu_mulai`,`h`.`waktu_selesai` AS `waktu_selesai`,`h`.`status_pengerjaan` AS `status_pengerjaan` from ((`hasil` `h` join `user` `u` on((`u`.`id_user` = `h`.`id_user`))) join `tryout` `t` on((`t`.`id_tryout` = `h`.`id_tryout`)));

DROP TABLE IF EXISTS `v_statistik_soal`;
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `v_statistik_soal` AS select `s`.`id_soal` AS `id_soal`,`s`.`pertanyaan` AS `pertanyaan`,`k`.`kode` AS `kategori`,`k`.`tipe_penilaian` AS `tipe_penilaian`,`s`.`tingkat_kesulitan` AS `tingkat_kesulitan`,count(`dh`.`id_detail`) AS `total_dijawab`,sum((case when (`dh`.`is_benar` = 1) then 1 else 0 end)) AS `total_benar`,round(((sum((case when (`dh`.`is_benar` = 1) then 1 else 0 end)) / nullif(count(`dh`.`id_detail`),0)) * 100),1) AS `pct_benar`,round(avg(`dh`.`poin_didapat`),2) AS `rata_poin` from ((`soal` `s` join `kategori` `k` on((`k`.`id_kategori` = `s`.`id_kategori`))) left join `detail_hasil` `dh` on((`dh`.`id_soal` = `s`.`id_soal`))) group by `s`.`id_soal`;

